Outcome<TaskEffect> finish_task_action(CommonStore&c,TaskState&s,SocialState&social,const TaskCatalog&catalog,const InteractionState&interaction,const InteractionCatalog&ic,const InteractionAccess&access,const ActionCoreView&action,Integer finish_tick,AffairsState*affairs,const TaskExecutionServices*execution,const TaskMessageNoticeServices*notices,const TaskMessageReturnServices*returns,const TaskPersonalMessageServices*personal,const TaskPersonalReportServices*personal_reports,const TaskPersonalAcceptanceServices*personal_acceptances,TaskExactWrite*exact){
 if(s.exact_execution.has_value()!=(exact!=nullptr))return {false,{},common_failure("TaskExactWriterContextRequired",action.id).error};
 if(exact&&exact->at.half_day_tick!=finish_tick)return {false,{},common_failure("TaskExactFinishMomentMismatch",action.id).error};
 const auto*params=s.actions.find(action.id);const auto*original_task=params?s.tasks.find(params->task_id):nullptr;
 const bool original_report=action.kind=="report_offer"&&original_task&&!original_task->contract_id;
 if(original_report&&social.original_relation_version==2){
  if(!exact||!exact->report_relations)return {false,{},common_failure("OriginalTaskReportRelationWriterRequired",action.id,ErrorKind::unsupported_capability).error};
  if(!exact->report_relations->bound_to(c,social,s))return {false,{},common_failure("OriginalTaskReportRelationCandidateMismatch",action.id,ErrorKind::internal).error};
  if(original_task->record_kind!=TaskRecordKind::legacy_quantity||original_task->exact_quantity)return {false,{},common_failure("OriginalTaskReportRelationSourceRequired",action.id,ErrorKind::unsupported_capability).error};
 }

 auto prefix=read_current_common_fact_prefix(c);if(!prefix.ok)return {false,{},prefix.error};const auto first_new_fact=static_cast<std::size_t>(prefix.value.common_fact_count);
 auto result=finish_task_action_original(c,s,social,catalog,interaction,ic,access,action,finish_tick,affairs,execution,notices,returns,personal,personal_reports,personal_acceptances,exact?&exact->at:nullptr,exact?exact->life:nullptr);if(!result.ok||!exact)return result;
 auto recorded=record_exact_task_terminal_in_candidate(c,s,catalog,action,result.value,first_new_fact,*exact);if(!recorded.ok)return {false,{},recorded.error};
 if(original_report&&social.original_relation_version==2){
  const TaskExactTerminalSource*terminal=nullptr;for(const auto&row:s.exact_execution->terminals.rows())if(row.second.action_id==action.id){if(terminal)return {false,{},common_failure("DuplicateTaskExactTerminal",action.id).error};terminal=&row.second;}
  if(!terminal)return {false,{},common_failure("TaskExactTerminalSourceRequired",action.id).error};
  if(terminal->effect.success&&terminal->task_status_after=="success"){
   auto applied=exact->report_relations->apply_original_task_report({"tasks","task_action_finished",terminal->id},task_exact_terminal_source_schema(s.exact_execution->version),exact->at);if(!applied.ok)return {false,{},applied.error};
  }
 }
 return result;
}

Status observe_escort_tasks(CommonStore& c,TaskState& s,const TaskCatalog& catalog){for(auto& row:s.tasks.rows()){auto& t=row.second;auto* d=resolve_task_definition(s,catalog,t);if(!d||d->template_id!="escort"||t.status!="active")continue;if(!t.escort)return common_failure("InvalidEscortState");auto* person=c.actor(d->goal.actor_id);if(!person)return common_failure("InvalidEscortPerson");auto members=c.members(t.assignee);bool same=members&&std::find(members->begin(),members->end(),person->id)!=members->end();auto location=c.resolved_location(person->id);if(!location.ok)return {false,{},location.error};if(!person->alive){escort_failed(t,c.tick(),"EscortPersonLost");continue;}if(same&&(std::holds_alternative<OnRouteLocation>(location.value)||std::holds_alternative<WildernessLocation>(location.value)))t.escort->departed=true;auto* place=std::get_if<SettlementLocation>(&location.value);if(t.escort->departed&&same&&place&&place->place_id==d->goal.destination_place_id){t.escort->arrival_tick=c.tick();t.objective_completed_tick=c.tick();t.status="ready";StableId id="escort:"+t.id;auto r=c.append_fact({id,"escort_arrival","tasks"});if(!r.ok)return r;s.facts.insert(id,{t.id,person->id,t.assignee,d->goal.destination_place_id,c.tick(),{}});}}return common_success();}
Status record_task_battle(CommonStore& c,TaskState& s,const TaskCatalog& catalog,const TaskProtectedBattle& battle){for(auto& row:s.tasks.rows()){auto& t=row.second;auto* d=resolve_task_definition(s,catalog,t);if(!d||d->template_id!="escort"||t.status!="active"||t.assignee!=battle.controller_id||std::find(battle.protected_actor_ids.begin(),battle.protected_actor_ids.end(),d->goal.actor_id)==battle.protected_actor_ids.end())continue;if(!t.escort)return common_failure("InvalidEscortState");if(std::find(t.escort->battle_ids.begin(),t.escort->battle_ids.end(),battle.id)==t.escort->battle_ids.end())t.escort->battle_ids.push_back(battle.id);if(battle.outcome=="protected_lost"||battle.outcome=="defeat")escort_failed(t,c.tick(),battle.outcome=="protected_lost"?"ProtectedPersonDown":"EscortDefeated");}return common_success();}
